-- MON HOC: INT4211
-- FILE: database/seed.sql
-- MO TA: Du lieu mau thuc te cho 13 bang nghiep vu:
--   - 35 nguoi_dung (1 Chu cua hang, 4 NV ban hang, 3 NV giao hang, 27 Khach hang)
--   - 10 danh_muc (>= 8 danh muc yeu cau)
--   - 12 nha_cung_cap
--   - 160 san_pham (>= 150 san pham yeu cau)
--   - 340 lo_hang (>= 300 lo hang yeu cau, phan bo lo da huy, lo da ban het, lo can han, lo con han)
--   - 20 khuyen_mai (khuyen mai lo can han, san pham, don hang)
--   - 120 don_hang trong vong 30 ngay gan nhat (>= 100 don hang yeu cau)
--   - 420 chi_tiet_don va 447 chi_tiet_don_lo (phan bo chinh xac theo FEFO)
--   - 25 kiem_ke, 20 huy_hang, 60 mua_thuong_xuyen, 50 thong_bao
-- =============================================================================

BEGIN;

-- Xoa du lieu cu va reset sequence de co the chay lai seed.sql nhieu lan
TRUNCATE TABLE
    thong_bao,
    mua_thuong_xuyen,
    huy_hang,
    kiem_ke,
    chi_tiet_don_lo,
    chi_tiet_don,
    don_hang,
    khuyen_mai,
    lo_hang,
    san_pham,
    nha_cung_cap,
    danh_muc,
    nguoi_dung
RESTART IDENTITY CASCADE;

