SELECT setval(pg_get_serial_sequence('nguoi_dung', 'id'), (SELECT COALESCE(MAX(id), 1) FROM nguoi_dung));
SELECT setval(pg_get_serial_sequence('danh_muc', 'id'), (SELECT COALESCE(MAX(id), 1) FROM danh_muc));
