INSERT INTO danh_muc (id, ma_danh_muc, ten_danh_muc, mo_ta, hinh_anh, trang_thai, ngay_tao) VALUES
(1, 'DM01', 'Sữa và Chế phẩm từ sữa', 'Sữa tươi tiệt trùng, sữa chua, sữa đặc, sữa hạt và phô mai các loại', 'https://images.supabase.co/storage/v1/object/public/categories/sua-che-pham.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(2, 'DM02', 'Đồ uống và Giải khát', 'Nước khoáng, nước ngọt có gas, trà đóng chai, nước trái cây và cà phê hòa tan', 'https://images.supabase.co/storage/v1/object/public/categories/do-uong.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(3, 'DM03', 'Mì, Miến, Cháo, Phở ăn liền', 'Mì gói, mì ly, phở, bún, miến và cháo ăn liền tiện lợi cho gia đình', 'https://images.supabase.co/storage/v1/object/public/categories/mi-an-lien.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(4, 'DM04', 'Gạo, Thực phẩm khô và Đồ hộp', 'Gạo thơm, đậu, hạt ngũ cốc, cá hộp, thịt hộp, xúc xích tiệt trùng và rong biển', 'https://images.supabase.co/storage/v1/object/public/categories/thuc-pham-kho.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(5, 'DM05', 'Gia vị và Dầu ăn', 'Dầu ăn, nước mắm, nước tương, hạt nêm, đường, muối, tương ớt và sốt gia vị', 'https://images.supabase.co/storage/v1/object/public/categories/gia-vi.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(6, 'DM06', 'Bánh kẹo và Đồ ăn vặt', 'Bánh quy, bánh bông lan, snack, kẹo dẻo, socola và hạt sấy khô', 'https://images.supabase.co/storage/v1/object/public/categories/banh-keo.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(7, 'DM07', 'Thực phẩm mát và Đông lạnh', 'Xúc xích tươi, chả giò, cá viên, há cảo, đậu hũ và kem lạnh bảo quản mát', 'https://images.supabase.co/storage/v1/object/public/categories/dong-lanh.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(8, 'DM08', 'Hóa mỹ phẩm và Chăm sóc cá nhân', 'Dầu gội, sữa tắm, kem đánh răng, bàn chải, nước súc miệng và sữa rửa mặt', 'https://images.supabase.co/storage/v1/object/public/categories/cham-soc-ca-nhan.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(9, 'DM09', 'Vệ sinh nhà cửa và Đồ gia dụng', 'Nước giặt, bột giặt, nước rửa chén, nước lau sàn, khăn giấy và túi rác', 'https://images.supabase.co/storage/v1/object/public/categories/ve-sinh-nha-cua.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days'),
(10, 'DM10', 'Chăm sóc mẹ và bé', 'Tã bỉm trẻ em, khăn ướt em bé, sữa tắm gội dịu nhẹ và bột ăn dặm', 'https://images.supabase.co/storage/v1/object/public/categories/me-va-be.jpg', 'HOAT_DONG', CURRENT_TIMESTAMP - INTERVAL '60 days');
